WITH unpacked AS (SELECT id, log_ts, level, status_code, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, COALESCE(context['trace'], 'unknown') AS trace_or_default, SHIFTRIGHT(status_code, 2) AS status_code_high, SIZE(context) AS num_context FROM app_logs) SELECT CASE WHEN status_code >= 401 THEN 'LARGE' ELSE 'SMALL' END AS status_code_tier, DATE_TRUNC('DAY', log_ts) AS activity_day, SIZE(COLLECT_SET(level)) AS num_levels, COUNT(CASE WHEN level = 'DEBUG' THEN 1 END) AS debug_count, COUNT_IF(level = 'WARN') AS warn_events, SORT_ARRAY(COLLECT_SET(level)) AS level_list, RANK() OVER (PARTITION BY CASE WHEN status_code >= 401 THEN 'LARGE' ELSE 'SMALL' END ORDER BY SIZE(COLLECT_SET(level)) DESC) AS num_levels_rank FROM unpacked GROUP BY status_code_tier, activity_day ORDER BY warn_events DESC
